pub unsafe extern "C" fn packing_store_be32(dst: *mut u8, value: u32) -> *mut u8 { unsafe { let b = value.to_be_bytes(); core::ptr::copy_nonoverlapping(b.as_ptr(), dst, 4); dst } }

#[unsafe(no_mangle)]
#[inline(never)]
pub unsafe extern "C" fn packing_load_le64(src: *const u8) -> u64 { unsafe { u64::from_le_bytes(core::ptr::read_unaligned(src.cast::<[u8; 8]>())) } }

#[unsafe(no_mangle)]
#[inline(never)]
pub unsafe extern "C" fn packing_store_le64(dst: *mut u8, value: u64) -> *mut u8 { unsafe { let b = value.to_le_bytes(); core::ptr::copy_nonoverlapping(b.as_ptr(), dst, 8); dst } }

#[unsafe(no_mangle)]
#[inline(never)]
pub unsafe extern "C" fn packing_load_be64(src: *const u8) -> u64 { unsafe { u64::from_be_bytes(core::ptr::read_unaligned(src.cast::<[u8; 8]>())) } }

#[unsafe(no_mangle)]
#[inline(never)]
pub unsafe extern "C" fn packing_store_be64(dst: *mut u8, value: u64) -> *mut u8 { unsafe { let b = value.to_be_bytes(); core::ptr::copy_nonoverlapping(b.as_ptr(), dst, 8); dst } }

#[unsafe(no_mangle)]
#[inline(never)]
pub unsafe extern "C" fn checksum_sum8(src: *const u8, n: u16) -> u8 { unsafe { let mut value = 0u8; for i in 0..n as usize { value = value.wrapping_add(*src.add(i)); } value } }

#[unsafe(no_mangle)]
#[inline(never)]
pub unsafe extern "C" fn checksum_sum16(src: *const u8, n: u16) -> u16 { unsafe { let mut value = 0u16; for i in 0..n as usize { value = value.wrapping_add(*src.add(i) as u16); } value } }

#[unsafe(no_mangle)]
#[inline(never)]
pub unsafe extern "C" fn checksum_crc16(src: *const u8, n: u16, value: u16) -> u16 { unsafe { let mut crc = value; for i in 0..n as usize { crc ^= (*src.add(i) as u16) << 8; for _ in 0..8 { crc = (crc << 1) ^ if crc & 0x8000 != 0 { 0x1021 } else { 0 }; } } crc } }

#[unsafe(no_mangle)]
#[inline(never)]
pub unsafe extern "C" fn dispatch_dense(value: u8) -> u16 { unsafe { match value { 0 => 7, 1 => 0, 2 => 99, 3 => 2, 4 => 1, 5 => 17, 6 => 31, 7 => 6, _ => u16::MAX } } }

#[unsafe(no_mangle)]
#[inline(never)]
pub unsafe extern "C" fn dispatch_sparse(value: u8) -> u16 { unsafe { match value { 0 => 7, 1 => 11, 7 => 3, 31 => 13, 128 => 5, 255 => 17, _ => 0 } } }

#[unsafe(no_mangle)]
#[inline(never)]
pub unsafe extern "C" fn dispatch_parser_state(src: *const u8, n: u16) -> u16 { unsafe { let mut acc = 0u16; let mut total = 0u16; let mut state = 0u8; for i in 0..n as usize { let c = *src.add(i); match c { b':' => state ^= 1, b',' => { total = total.wrapping_add(acc); acc = 0; }, _ => { if c >= b'0' && c <= b'9' { acc = acc.wrapping_mul(10).wrapping_add((c - b'0') as u16); } else if c != b' ' { state = 2; } } } } total ^ acc ^ state as u16 } }
